struct Node { val: i32, left: Option<Box<Node>>, right: Option<Box<Node>> }

fn contains(root: &Option<Box<Node>>, target: i32) -> bool {
    match root {
        None => false,
        Some(n) if target == n.val => true,
        Some(n) if target < n.val => contains(&n.left, target),
        Some(n) => contains(&n.right, target),
    }
}

